#include "apps.h"
#include "app_stage_e.h"
#include "vfs.h"
#include "fat32.h"
#include "heap.h"
typedef struct{uint64_t used;int files;int selected;bool confirm;char status[64];}capacity_t;
static void cap_refresh(capacity_t*s){s->used=0;s->files=0;for(int i=0;i<vfs_count();i++){vfs_node_t*n=vfs_at(i);if(n&&n->name[0]=='/'&&n->name[1]=='d'){s->used+=n->size;s->files++;}}se_copy(s->status,fat32_is_mounted()?"storage index refreshed":"No FAT32 - read-only RAM view",64);}
static void cap_draw(window_t*w,const gfx_target_t*t){capacity_t*s=w->user_data;const ui_runtime_theme_t*h=ui_theme_current();gfx_clear(t,h->canvas);se_header(t,"CAPACITY - STORAGE AS STRATA","Capacity",false);uint64_t total=64ULL*1024*1024,free=total>s->used?total-s->used:0;char u[24],f[24],ct[24];se_num(u,s->used/1024);se_num(f,free/1024);se_num(ct,s->files);se_card(t,78,108,620,300,h->surface,h->border);se_text(t,104,136,"SANCTUM CAPACITY",h->muted);ui_draw_ring(t,260,264,104,14,(uint8_t)(s->used*255/total),h->border,h->accent_berry);se_bold(t,224,252,u,h->ink);se_text(t,224,278,"KB used",h->muted);se_bold(t,414,206,"64 MB volume",h->ink);se_text(t,414,244,"free KB",h->muted);se_bold(t,510,244,f,h->ink);se_text(t,414,282,"indexed files",h->muted);se_bold(t,542,282,ct,h->ink);se_progress(t,414,328,226,(uint8_t)(s->used*255/total),h->border,h->accent_berry);se_card(t,78,432,620,230,h->surface,h->border);se_text(t,104,460,"FILE-TYPE STRATA",h->muted);const char*ty[4]={"system / binaries","audio / media","notes / calendar","other warm data"};for(int i=0;i<4;i++){se_text(t,104,500+i*36,ty[i],h->ink);se_progress(t,330,506+i*36,320,(uint8_t)(50+i*38),h->border,ui_sunset((uint8_t)(i*60)));}
int x=740;se_card(t,x,108,w->width-x-70,554,h->surface,h->border);se_text(t,x+28,136,"BIGGEST FILES",h->muted);int y=176,shown=0;for(int pass=0;pass<5;pass++){vfs_node_t*best=0;for(int i=0;i<vfs_count();i++){vfs_node_t*n=vfs_at(i);if(!n||n->name[0]!='/')continue;if(pass==0||n->size<(best?best->size:(uint64_t)-1))best=n;}if(best&&shown<5){char sz[24];se_num(sz,best->size/1024);se_card(t,x+24,y,w->width-x-118,64,h->surface_soft,h->border);se_bold(t,x+44,y+14,best->name,h->ink);se_text(t,w->width-164,y+34,sz,h->muted);y+=78;shown++;}}if(!shown)se_text(t,x+28,190,"No indexed files",h->muted);se_card(t,78,688,w->width-148,150,h->surface,h->border);se_text(t,104,716,"CLEANUP",h->muted);se_bold(t,104,754,s->confirm?"Press C again to remove safe cache":"Only known temporary cache is eligible",h->ink);se_text(t,104,790,"R refresh     C safe cleanup     Esc back",h->muted);se_text(t,78,w->height-34,s->status,h->accent_berry);}
static void cap_key(window_t*w,char c){capacity_t*s=w->user_data;if(c==27){se_close(w);return;}if(c=='r'||c=='R')cap_refresh(s);else if(c=='c'||c=='C'){if(!s->confirm){s->confirm=true;se_copy(s->status,"Press C again to confirm safe cleanup",64);}else{s->confirm=false;int r=fat32_delete_file("/disk/Sanctum/cache.tmp");se_copy(s->status,r==0?"temporary cache removed":"No safe cache to remove",64);cap_refresh(s);}}}
window_t* app_capacity_open(void){capacity_t*s=kmalloc(sizeof(*s));if(!s)return 0;s->selected=0;s->confirm=false;cap_refresh(s);window_t*w=se_workspace("Capacity",cap_draw,0,cap_key,s,false);if(!w)kfree(s);return w;}
